import{_ as l,a0 as r,w as o,s as d,I as n,x as e,a1 as i,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"从 Linux 终端打印文件 | LCTT x X-CMD","titleTemplate":false,"description":"从 Linux 终端打印文件 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"从 Linux 终端打印文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"从 Linux 终端打印文件 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210903 Print files from your Linux terminal","title":"从 Linux 终端打印文件","tag":"202112","desc":""},"relativePath":"202112/20210903 Print files from your Linux terminal.md","filePath":"[post].md"}'),u={name:"202112/20210903 Print files from your Linux terminal.md"};function c(h,s,g,f,b,k){const a=r("Link");return o(),d("div",null,[s[26]||(s[26]=n("h1",{id:"从-linux-终端打印文件",tabindex:"-1"},[e("从 Linux 终端打印文件 "),n("a",{class:"header-anchor",href:"#从-linux-终端打印文件","aria-label":"Permalink to “从 Linux 终端打印文件”"},"​")],-1)),s[27]||(s[27]=n("blockquote",null,[n("p",null,"使用 lpr 命令在终端中打印文件。")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202112/20/135809an6s6bxyg7sjnwyq.jpg",alt:""})],-1)),n("p",null,[i(a,{href:"https://opensource.com/article/21/8/setup-your-printer-linux"},{default:t(()=>[...s[0]||(s[0]=[e("在 Linux 上打印很容易",-1)])]),_:1}),s[1]||(s[1]=e("，但有时感觉要做很多工作，比如启动应用程序、打开文件、在菜单中找到打印选项，单击确认按钮等等。当你是一个终端用户时，通常希望使用简单的触发器执行复杂的操作。打印很复杂，但没有什么比 ",-1)),s[2]||(s[2]=n("code",null,"lpr",-1)),s[3]||(s[3]=e(" 命令更简单了。",-1))]),s[29]||(s[29]=p(`<h3 id="使用-lpr-命令打印" tabindex="-1">使用 lpr 命令打印 <a class="header-anchor" href="#使用-lpr-命令打印" aria-label="Permalink to “使用 lpr 命令打印”">​</a></h3><p>使用 <code>lpr</code> 命令在终端打印文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpr myfile.odt</span></span></code></pre></div><p>如果失败的话，你需要设置默认打印机或手动指定打印机。</p><h3 id="设置默认打印机" tabindex="-1">设置默认打印机 <a class="header-anchor" href="#设置默认打印机" aria-label="Permalink to “设置默认打印机”">​</a></h3><p>根据我在 1984 年印刷的 Berkeley 4.2 手册的旧版本中找到的资料，<code>lpr</code> 命令会分页并将文件发送到打印机池，后者将数据传输到称为 <ruby>行式打印机<rt>line printer</rt></ruby> 的东西。</p><p><img src="https://opensource.com/sites/default/files/berkeley-1984-lpr.jpeg" alt="显示 LPR 命令信息的页面"></p><p>现在，最初的 <code>lpr</code> 命令已经无法满足，因为现代计算机可以访问多台打印机，而且是那些比点阵行式打印机复杂得多的打印机。现在有一个称为<ruby>通用 Unix 打印系统<rt>Common Unix Printing System</rt></ruby>（CUPS）子系统，可以跟踪你的计算机可以访问的所有打印机，计算机应该使用哪个驱动程序与每台打印机通信，默认使用哪台打印机等等。 CUPS 捆绑提供的 <code>lpr.cups</code> 或 <code>lpr-cups</code> 命令通常以符号链接到 <code>lpr</code>，允许你首先借助 CUPS 配置从终端打印。</p><p>使用 <code>lpr</code> 打印文件，你应该首先设置默认打印机。你可以在系统的打印机设置中设置：</p><p><img src="https://opensource.com/sites/default/files/printer-default.jpeg" alt="设置默认打印机对话框"></p><p>或者，你也可以使用 <code>lpadmin</code> 命令设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lpadmin -d HP_LaserJet_P2015_Series</span></span>
<span class="line"><span>$ lpstat -v</span></span>
<span class="line"><span>device for HP_LaserJet_P2015_Series: ipp://10.0.1.222:631/printers/HP_LaserJet_P2015_Series</span></span></code></pre></div><h3 id="使用环境变量设置" tabindex="-1">使用环境变量设置 <a class="header-anchor" href="#使用环境变量设置" aria-label="Permalink to “使用环境变量设置”">​</a></h3>`,13)),n("p",null,[s[5]||(s[5]=e("你不能在没有管理员账户的系统上设置默认打印机，因为更改打印机默认设置是一项特权任务。在 ",-1)),s[6]||(s[6]=n("code",null,"lpr",-1)),s[7]||(s[7]=e(" 借助 CUPS 找到目标打印机前，它会在系统中查询 ",-1)),s[8]||(s[8]=n("code",null,"PRINTER",-1)),s[9]||(s[9]=e()),i(a,{href:"https://opensource.com/article/19/8/what-are-environment-variables"},{default:t(()=>[...s[4]||(s[4]=[e("环境变量",-1)])]),_:1}),s[10]||(s[10]=e("。",-1))]),s[30]||(s[30]=p(`<p>在本例中，<code>HP_LaserJet_P2015_Series</code> 是打印机的名称。将 <code>PRINTER</code> 设置为该值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ PRINTER=HP_LaserJet_P2015_Series</span></span>
<span class="line"><span>$ export PRINTER</span></span></code></pre></div><p>一旦设置了 <code>PRINTER</code> 变量，你就可以打印了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpr myfile.pdf</span></span></code></pre></div><h3 id="获取连接的打印机列表" tabindex="-1">获取连接的打印机列表 <a class="header-anchor" href="#获取连接的打印机列表" aria-label="Permalink to “获取连接的打印机列表”">​</a></h3><p>你可以使用 <code>lpstat</code> 命令查看所有连接到系统接受打印任务的打印机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpstat -a</span></span>
<span class="line"><span>HP_LaserJet_P2015_Series accepting requests since Sun 1 Aug 2021 10:11:02 PM NZST</span></span>
<span class="line"><span>r1060 accepting requests since Wed 18 Aug 2021 04:43:57 PM NZST</span></span></code></pre></div><h3 id="打印到任意一台打印机" tabindex="-1">打印到任意一台打印机 <a class="header-anchor" href="#打印到任意一台打印机" aria-label="Permalink to “打印到任意一台打印机”">​</a></h3><p>将打印机添加到系统后，并且现在你知道如何识别它们了，你可以打印到其中任何一台，无论你是否设置了默认打印机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpr -P HP_LaserJet_P2015_Series myfile.txt</span></span></code></pre></div><h3 id="如何定义打印机" tabindex="-1">如何定义打印机 <a class="header-anchor" href="#如何定义打印机" aria-label="Permalink to “如何定义打印机”">​</a></h3><p>CUPS 有一个友好的前端页面，可通过 Web 浏览器如 Firefox 访问。虽然它使用 Web 浏览器作为用户界面，但它实际上是在本机（一个称为 <code>localhost</code> 的位置）的 631 端口上提供服务。CUPS 管理连接到计算机的打印机，并将其配置存储在 <code>/etc/cups/priters.conf</code> 中。</p><p><code>printers.conf</code> 文件包含详细描述计算机可以访问的打印设备的定义。不要直接编辑它，但如果你想这样做，你必须先停止 <code>cupsd</code> 守护进程。</p><p>一个典型的文件定义如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;Printer r1060&gt;</span></span>
<span class="line"><span>  Info Ricoh 1060</span></span>
<span class="line"><span>  Location Downstairs</span></span>
<span class="line"><span>  MakeModel Ricoh Aficio 1060 - CUPS+Gutenprint v5.2.6</span></span>
<span class="line"><span>  DeviceURI lpd://192.168.4.8</span></span>
<span class="line"><span>  State Idle</span></span>
<span class="line"><span>  StateTime 1316011347</span></span>
<span class="line"><span>  Type 12308</span></span>
<span class="line"><span>  Filter application/vnd.cups-raw 0 -</span></span>
<span class="line"><span>  Filter application/vnd.cups-raster 100 rastertogutenprint.5.2</span></span>
<span class="line"><span>  Accepting Yes</span></span>
<span class="line"><span>  Shared No</span></span>
<span class="line"><span>  JobSheets none none</span></span>
<span class="line"><span>  QuotaPeriod 0</span></span>
<span class="line"><span>  PageLimit 0</span></span>
<span class="line"><span>  KLimit 0</span></span>
<span class="line"><span>  OpPolicy default</span></span>
<span class="line"><span>  ErrorPolicy stop-printer</span></span>
<span class="line"><span>&lt;/Printer&gt;</span></span></code></pre></div><p>在本例中，打印机的名称是 <code>r1060</code>，即 “Ricoh Aficio 1060”。</p><p><code>MakeModel</code> 属性是从 <code>lpinfo</code> 命令中提取的，该命令列出了系统上所有可用的打印机驱动程序。假设你知道要打印到 Ricoh Aficio 1060，那么你会发出以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpinfo -m | grep 1060</span></span>
<span class="line"><span>gutenprint.5.2://brother-hl-1060/expert Brother HL-1060 - CUPS+Gutenprint v5.2.11</span></span>
<span class="line"><span>gutenprint.5.2://ricoh-afc_1060/expert Ricoh Aficio 1060 - CUPS+Gutenprint v5.2.11</span></span></code></pre></div><p>它会列出已安装的相关驱动程序。</p><p><code>MakeModel</code> 属性是结果的后半部分。在本例中为 <code>Ricoh Aficio 1060 - CUPS+Gutenprint v5.2.11</code>。</p><p><code>DeviceURI</code> 属性标识打印机在网络上的位置（或物理位置，例如 USB 端口）。在本例中，它是 <code>lpd://192.168.4.8</code>，因为我使用 <code>lpd</code> 协议将数据发送到一台网络打印机。在我的另一个系统上，我有一个通过 USB 连接的 HP LaserJect 打印机，因此 <code>DeviceURI</code> 是 <code>hp:/usb/HP_LaserJet_P2015_Series?serial=00CNCJM26429</code>。</p><h3 id="在终端中打印" tabindex="-1">在终端中打印 <a class="header-anchor" href="#在终端中打印" aria-label="Permalink to “在终端中打印”">​</a></h3><p>将作业发送到打印机是一个简单的过程，只要你了解连接到系统的设备以及如何识别它们。在终端打印非常快速、高效，并且易于编写脚本或作为批处理作业完成。试试看！</p><hr>`,24)),n("p",null,[s[12]||(s[12]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/9/print-files-linux"},{default:t(()=>[...s[11]||(s[11]=[e("https://opensource.com/article/21/9/print-files-linux",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[13]||(s[13]=[e("Seth Kenlon",-1)])]),_:1}),s[18]||(s[18]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 译者：",-1)),i(a,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[15]||(s[15]=[e("MjSeven",-1)])]),_:1}),s[20]||(s[20]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[e("Linux中国",-1)])]),_:1}),s[25]||(s[25]=e(" 荣誉推出",-1))])])}const C=l(u,[["render",c]]);export{x as __pageData,C as default};
